/**
 * Homepage-Bilder (docs/landingpage.md): realistic pictures for the public
 * pages – the farm behind the start page, bees next to the Bienen module and
 * so on – generated by Google's image models when the owner asks for them in
 * Verwaltung, stored in the image storage like other photos and served to
 * every visitor. Until a slot has a picture the homepage shows its drawing.
 */

import { db, siteImagesTable } from '@workspace/db';
import { eq } from 'drizzle-orm';

import { FarmDataError } from './farmAnimals';
import { deleteImageByUrl, uploadImage } from './imageStorage';
import { logger } from './logger';

export interface SiteImageSlot {
  title: string;
  aspect: '16:9' | '4:3' | '1:1';
  prompt: string;
}

/** Same look for all: warm, natural, Central European, no text. */
export const STYLE =
  'Realistic photograph, warm natural daylight, soft depth of field, inviting and calm, a small family farm in Central Europe (Germany), authentic and not staged, no text, no letters, no logos, no watermark.';

/** The slots of the homepage; the app knows the same keys (lib/site.ts). */
export const SITE_IMAGE_SLOTS = {
  hero: { title: 'Startseite: der Hof', aspect: '16:9', prompt: 'Wide view over a small family farm in the morning: a red-brown wooden barn, a vegetable garden with raised beds, chickens on a green meadow, an apple tree, rolling hills behind.' },
  plants: { title: 'Pflanzen', aspect: '4:3', prompt: 'Bright window sill with lush house plants (monstera, herbs in pots, a flowering geranium), a hand holding a smartphone photographing a leaf.' },
  garden: { title: 'Beet-Architekt', aspect: '4:3', prompt: 'Wooden raised bed full of vegetables – tomatoes, lettuce, carrots, marigolds between them – in a sunny garden, a watering can beside it.' },
  herbs: { title: 'Kräuter-Hexe', aspect: '4:3', prompt: 'Freshly picked medicinal and kitchen herbs – chamomile, sage, peppermint, calendula – on a rustic wooden table with small bundles drying.' },
  pantry: { title: 'Vorratskammer', aspect: '4:3', prompt: 'Shelf in a cool cellar pantry with glass jars of preserved vegetables, jams and honey, handwritten paper labels without readable text.' },
  animals: { title: 'Tiere', aspect: '4:3', prompt: 'Happy free-range chickens of mixed breeds pecking on a green meadow in front of a small wooden chicken coop.' },
  goats: { title: 'Futter & Zucht', aspect: '4:3', prompt: 'Two goats and a young kid at a wooden hay rack in a clean, bright stable door opening onto a pasture.' },
  pasture: { title: 'Weide', aspect: '4:3', prompt: 'Sheep grazing on a fenced green pasture with a wooden fence and a meadow with wildflowers, gentle hills.' },
  bees: { title: 'Bienen', aspect: '4:3', prompt: 'Close view of wooden beehives at the edge of a flowering orchard, honey bees flying at the entrance, a beekeeper in a light veil in the soft background.' },
  team: { title: 'Gemeinsam auf dem Hof', aspect: '4:3', prompt: 'A family of three generations working together on a small farm, feeding chickens and carrying a basket of vegetables, smiling, seen from a little distance.' },
  pricing: { title: 'Preise & Pakete', aspect: '4:3', prompt: 'A wicker basket with fresh eggs, vegetables from the garden and a jar of honey on a wooden table outside, farm in the soft background.' },
} satisfies Record<string, SiteImageSlot>;

export type SiteImageKey = keyof typeof SITE_IMAGE_SLOTS;

export function isSlot(key: string): key is SiteImageKey {
  return Object.hasOwn(SITE_IMAGE_SLOTS, key);
}

/** Image models in order: Gemini image generation, then Imagen. */
export const IMAGE_MODELS = ['gemini-2.5-flash-image', 'imagen-4.0-generate-001'] as const;

export function fullPrompt(slot: SiteImageSlot, extra?: string | null): string {
  return [slot.prompt, extra?.trim(), STYLE].filter(Boolean).join(' ');
}

/** The picture as a data URL from one model, or throws. */
async function generateWith(model: string, prompt: string, aspect: string): Promise<string> {
  const { ai } = await import('./geminiClient');
  if (model.startsWith('imagen')) {
    const res = await ai.models.generateImages({ model, prompt, config: { numberOfImages: 1, aspectRatio: aspect } });
    const image = res.generatedImages?.[0]?.image;
    if (!image?.imageBytes) throw new Error('No image in the answer');
    return `data:${image.mimeType ?? 'image/png'};base64,${image.imageBytes}`;
  }
  const res = await ai.models.generateContent({
    model,
    contents: prompt,
    config: { responseModalities: ['IMAGE'], imageConfig: { aspectRatio: aspect } },
  });
  const part = res.candidates?.[0]?.content?.parts?.find((p) => p.inlineData?.data);
  if (!part?.inlineData?.data) throw new Error('No image in the answer');
  return `data:${part.inlineData.mimeType ?? 'image/png'};base64,${part.inlineData.data}`;
}

export async function listSiteImages(): Promise<Record<string, string>> {
  const rows = await db.select({ slot: siteImagesTable.slot, url: siteImagesTable.url }).from(siteImagesTable);
  return Object.fromEntries(rows.filter((r) => isSlot(r.slot)).map((r) => [r.slot, r.url]));
}

/** For Verwaltung: every slot with its prompt and the picture, if any. */
export async function siteImageAdmin() {
  const rows = await db.select().from(siteImagesTable);
  const bySlot = new Map(rows.map((r) => [r.slot, r]));
  return (Object.entries(SITE_IMAGE_SLOTS) as [SiteImageKey, SiteImageSlot][]).map(([slot, s]) => {
    const row = bySlot.get(slot);
    return { slot, title: s.title, aspect: s.aspect, prompt: s.prompt, url: row?.url ?? null, model: row?.model ?? null, createdAt: row ? row.createdAt.toISOString() : null };
  });
}

/** Generates a slot's picture (first model that answers), stores it and drops the old one. */
export async function generateSiteImage(key: string, extra?: string | null) {
  if (!isSlot(key)) throw new FarmDataError(404, 'Diesen Bildplatz gibt es nicht.');
  const slot = SITE_IMAGE_SLOTS[key];
  const prompt = fullPrompt(slot, extra ? extra.slice(0, 300) : null);
  let dataUrl: string | null = null;
  let model = '';
  for (const m of IMAGE_MODELS) {
    try {
      dataUrl = await generateWith(m, prompt, slot.aspect);
      model = m;
      break;
    } catch (err) {
      logger.warn({ err, model: m, slot: key }, 'Site image generation failed');
    }
  }
  if (!dataUrl) throw new FarmDataError(502, 'Die Bild-KI hat kein Bild geliefert. Bildmodelle brauchen bei Google meist ein bezahltes Kontingent – bitte später erneut versuchen.');
  let url: string;
  try {
    url = await uploadImage(dataUrl, 60_000);
  } catch {
    throw new FarmDataError(502, 'Das Bild konnte nicht gespeichert werden.');
  }
  const [old] = await db.select({ url: siteImagesTable.url }).from(siteImagesTable).where(eq(siteImagesTable.slot, key));
  await db
    .insert(siteImagesTable)
    .values({ slot: key, url, prompt, model })
    .onConflictDoUpdate({ target: siteImagesTable.slot, set: { url, prompt, model, createdAt: new Date() } });
  if (old && old.url !== url) void deleteImageByUrl(old.url).catch(() => false);
  return siteImageAdmin();
}

export async function deleteSiteImage(key: string) {
  if (!isSlot(key)) throw new FarmDataError(404, 'Diesen Bildplatz gibt es nicht.');
  const [gone] = await db.delete(siteImagesTable).where(eq(siteImagesTable.slot, key)).returning({ url: siteImagesTable.url });
  if (gone) void deleteImageByUrl(gone.url).catch(() => false);
  return siteImageAdmin();
}
